import java.util.*;

public class Hello {
    @SuppressWarnings({"all"})
    public static void main(String[] args){
        ArrayList arrayList = new ArrayList();
        arrayList.add("张三3");
        arrayList.add("李四41");
        arrayList.add("王五523");
