        Iterator<Map.Entry<String,T>> iterator = set.iterator();
        List<T> list = new ArrayList<>();
        while (iterator.hasNext()) {
            Map.Entry<String, T> next =  iterator.next();
            list.add(next.getValue());
        }
        return list;
    }

    public void delete(String id) {
        map.remove(id);
    }
