        thread.interrupt();//提前结束了休眠，并且抛出错误
    }
}

class c implements Runnable {
    private int num;

    @Override
    public void run() {
        System.out.println("现在线程:" + Thread.currentThread().getName() + "开始运行");
        while (true) {
            if(num >=5){
                break;
