            System.out.println("这是一个线程:" + (++num));
            try {
                Thread.sleep(500);//用于休眠0.5s
            } catch (InterruptedException e) {
                System.out.println("捕获到 " + Thread.currentThread().getName() + " 的中断异常");
                e.printStackTrace();
            }
        }
        System.out.println("现在线程:" + Thread.currentThread().getName() + "结束运行");
    }
}

