        String fileName = "Hello.txt";
        File file = new File(fileParentPath, fileName);

        byte[] b = new String("hello,world").getBytes();
        if (file.exists()) {
            FileOutputStream fileOutputStream = new FileOutputStream(file);
            // 0表示从byte数组索引0开始读取
            // b.length就是指定的传入的长度
            fileOutputStream.write(b, 0, b.length);
