        *   }
        *   最后的结果是,num = 100
        * */
        // 注意这里只是类加载的阶段，所以就还没到对象的阶段
        System.out.println(A.num);
    }
}

class A {
    static {
        System.out.println("这是A里面的静态代码块");
        num = 300;
    }
    static int num = 100;

    public A() {}
}
