            preparedStatement.setInt(2, 2);
            int rows = preparedStatement.executeUpdate();
            System.out.println(rows > 0 ? "成功" : "失败");
            // 3.关闭资源
            JDBCUtils.close(null, preparedStatement, connection);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
