		<script type="text/javascript">
			$(function() {
                //直接获取Jquery对象
				$('.main');
				console.dir($('.main'));

                //将DOM对象转换为JQuery对象
				var JQuery_main = document.querySelector('.main');
				$(JQuery_main);
				console.dir($(JQuery_main));
			})
		</script>
	</head>
	<body>
		<div class="main"></div>
	</body>
</html>

```

