## 7.8 实现显式绑定

下面是通过`JS`来实现`call/apply/bind`方法

```javascript
function CallOrApplyOrBind() {}

// call方法
Function.prototype.call = function (thisArg, ...args) {
  // 因为使用的fn.call()来调用的该函数，为隐式绑定，所以this就是fn
  var fn = this;
  /*
    1.Object()可以将number、String...类型转换为Object类型
    2.当传入的是null、undefined的时候返回的是window
  */
  thisArg =
    thisArg !== null || thisArg !== undefined ? Object(thisArg) : window;

  // 给传入的对象中加入this的函数，即fn
  thisArg.fn = fn;
  // 执行该函数，并且传入参数
  var result = thisArg.fn(...args);
  delete thisArg.fn;

  return result;
};

// apply方法
Function.prototype.apply = function (thisArg, args = []) {
  // 和call的区别在于传递的是[]
  var fn = this;

  thisArg =
    thisArg !== null || thisArg !== undefined ? Object(thisArg) : window;

  thisArg.fn = fn;
  var result = thisArg.fn(...args);
  delete thisArg.fn;

  return result;
};

// bind方法
Function.prototype.bind = function (thisArg, ...args) {
  var fn = this;
  thisArg =
    thisArg !== null || thisArg !== undefined ? Object(thisArg) : window;

  return function (...ParmBindArgs) {
    thisArg.fn = fn;
    var result = thisArg.fn(...args, ...ParmBindArgs);
    delete thisArg.fn;

    return result;
  };
};


// 下面为实现的案例
let obj = {
  name: "张三",
};
function fn(a, b, c, d) {
  console.log(this, a, b, c, d);
}
fn.call("123", 1, 2, 3, 4);
fn.apply(obj, [1, 2, 3, 4]);

let result = fn.bind(obj, 1, 2);
result(3, 4);
```

