// Promise封装
function axios({ url, method = "get", timeout = "10000", data } = {}) {
  const xhr = new XMLHttpRequest();

  const ResultPromise = new Promise((resolve, reject) => {
    xhr.onload = function () {
      if (xhr.status >= 200 && xhr.status <= 300) {
        resolve(xhr.response);
      } else {
        reject(xhr.statusText);
      }
    };

    xhr.responseType = "json";
    xhr.timeout = timeout;

    if (method.toUpperCase() === "GET") {
      // 拼接query参数
      const queryStrings = [];
      for (const key in data) {
        queryStrings.push(`${key}=${data[key]}`);
      }
      url = url + "?" + queryStrings.join("&");
      xhr.open(method, url);
      xhr.send();
    } else {
      xhr.open(method, url);
      xhr.setRequestHeader("Content-type", "application/json");
      xhr.send(JSON.stringify(data));
    }
  });

  ResultPromise.xhr = xhr;

  return ResultPromise;
}

axios({
  url: "http://123.207.32.32:8000/home/multidata",
  success(res) {
    console.log(res);
  },
  failure(rej) {
    console.log(rej);
  },
});

axios({
  url: "http://123.207.32.32:1888/02_param/get",
  data: {
    name: "zs",
    age: 18,
  },
  success(res) {
    console.log(res);
  },
  failure(rej) {
    console.log(rej);
  },
});

axios({
  url: "http://123.207.32.32:1888/02_param/postjson",
  method: "post",
  data: { name: "zs", age: 18 },
  success(res) {
    console.log(res);
  },
  failure(rej) {
    console.log(rej);
  },
});

const promiseXHR = axios({
  url: "http://123.207.32.32:8000/home/multidata",
});
promiseXHR.then((res, rej) => {
  console.log(res);
});
console.log(promiseXHR.xhr);

