app.use(router.routes());

router.post("/GetJSONorGetUrlencoded", (context, next) => {
  console.log(context.request.body); // 同时解析JSON和urlencoded数据
  context.response.body = "获取JSON数据";
});

app.listen(HTTP_PORT, () => {
