### 11.2.2 基本使用

```javascript
const fs = require("fs");

const read = fs.createReadStream("./1.txt", {
  start: 1, // 读取开始位置，默认为0，单位是字节
  end: 8, // 读取结束位置，默认为Infinity，单位是字节
  highWaterMark: 4, // 读取的大小 默认是64 * 1024 单位是字节
});
// 其实这里就可以看出Stream继承了Event
// 当打开文件
read.on("open", (fd) => {
  console.log("文件被打开了");
});
// 当读取到文件
read.on("data", (data) => {
  console.log(data, data.toString());
  // 读取停止
  read.pause();
  // 文件读取恢复
  setTimeout(() => {
    read.resume();
  }, 100);
});
// 当文件读取结束
read.on("end", () => {
  console.log("文件读取结束");
});
// 当文件被关闭
read.on("close", () => {
  console.log("文件被关闭");
});
```

