      type: DataTypes.INTEGER,
      primaryKey: true,
      autoIncrement: true,
    },
    studentId: {
      type: DataTypes.INTEGER,
      /*
      	 因为不识别下划线的写法，所以field就是映射数据表的字段
      	 studentId -> student_id
      */
      field: "student_id",
      allowNull: false,
      references: { // 设置外键
        model: Students,
        key: "id",
      },
    },
    courseId: {
      type: DataTypes.INTEGER,
      allowNull: false,
      field: "course_id",
      references: {
        model: Courses,
        key: "id",
      },
    },
  },
  {
    tableName: "students_select_courses", // 明确与数据库的关系映射
    createdAt: false,
    updatedAt: false,
    sequelize,
  }
);

// 设置多对多的映射关系
Students.belongsToMany(Courses, {
  through: students_select_courses,
  foreignKey: "student_id",
  otherKey: "course_id",
});

Courses.belongsToMany(Students, {
  through: students_select_courses,
  foreignKey: "course_id",
  otherKey: "student_id",
});

async function query() {
  const result = await Students.findAll({
    include: {
      model: Courses,
    },
  });
  console.log(result)
}
query();
```

