下面是我自己实现的写法

```react
<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta http-equiv="X-UA-Compatible" content="IE=edge" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Document</title>
    <style>
      .BookTable {
        border-collapse: collapse;
      }
      .BookTable th,
      td {
        border: 1px solid #aaa;
        padding: 8px 16px;
      }
      .SelectTr {
        background-color: cadetblue;
        opacity: 0.5;
      }
    </style>
  </head>
  <body>
    <script src="../依赖包/react.development.js"></script>
    <script src="../依赖包/react-dom.development.js"></script>
    <script src="../依赖包/babel.min.js"></script>

    <div id="root"></div>

    <script type="text/babel">
      class App extends React.Component {
        constructor() {
          super();
          this.state = {
            booklist: [
              {
                id: 1,
                name: "Java基础",
                time: "2022-12-12",
                price: 12,
                num: 1,
              },
              {
                id: 2,
                name: "JavaScript基础",
                time: "2022-12-12",
                price: 12,
                num: 1,
              },
              {
                id: 3,
                name: "Go基础",
                time: "2022-12-12",
                price: 12,
                num: 1,
              },
              {
                id: 4,
                name: "CSS基础",
                time: "2022-12-12",
                price: 12,
                num: 1,
              },
            ],
            currentIndex: -1,
          };
        }
        countBookNum(index, count) {
          let newBookList = [...this.state.booklist];
          newBookList[index].num += count;

          this.setState({
            booklist: newBookList,
          });
        }
        removeBook(index) {
          let newBookList = [...this.state.booklist];
          newBookList.splice(index, 1);

          this.setState({
            booklist: newBookList,
          });
        }
        countBookPrice(item) {
          return item.num * item.price;
        }
        formatBookPrice(price) {
          return `￥${price}`;
        }
        countBookTotalPrice(booklist) {
          const total = booklist.reduce((preValue, oldValue) => {
            return preValue + oldValue.num * oldValue.price;
          }, 0);

          return total;
        }
        selectBook(index) {
          if (index == this.state.currentIndex) {
            this.setState({
              currentIndex: -1,
            });
          } else {
            this.setState({
              currentIndex: index,
            });
          }
        }
        renderBookTable() {
          const { booklist, currentIndex } = this.state;
          const { countBookPrice, formatBookPrice, countBookTotalPrice } = this;

          return (
            <div>
              <table className="BookTable">
                <thead>
                  <tr>
                    <th></th>
                    <th>书籍名称</th>
                    <th>出版日期</th>
                    <th>价格</th>
                    <th>购买数量</th>
                    <th>操作</th>
                  </tr>
                </thead>
                <tbody>
                  {booklist.map((item, index) => (
                    <tr
                      key={index}
                      className={currentIndex == index ? "SelectTr" : ""}
                    >
                      <td onClick={() => this.selectBook(index)}>{item.id}</td>
                      <td>{item.name}</td>
                      <td>{item.time}</td>
                      <td>{formatBookPrice(countBookPrice(item))}</td>
                      <td>
                        <button
                          onClick={() => this.countBookNum(index, -1)}
                          disabled={item.num <= 0}
                        >
                          -1
                        </button>
                        {item.num}
                        <button onClick={() => this.countBookNum(index, 1)}>
                          +1
                        </button>
                      </td>
                      <td>
                        <button onClick={() => this.removeBook(index)}>
                          删除
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <h3>总价：{formatBookPrice(countBookTotalPrice(booklist))}</h3>
            </div>
          );
        }
        renderNullBookTable() {
          return (
            <div>
              <h3>没有更多的数据~</h3>
            </div>
          );
        }
        render() {
          const { booklist } = this.state;

          return (
            <div>
              {booklist.length == 0
                ? this.renderNullBookTable()
                : this.renderBookTable()}
            </div>
          );
        }
      }

      const root = ReactDOM.createRoot(document.querySelector("#root"));
      root.render(<App />);
    </script>
  </body>
</html>

```

