```javascript
const num = [1, 2, 3, 4, 5, NaN];
// 1.以前的处理方式
if (num.indexOf(1) !== -1) {
  console.log("该数字存在~");
}

// 2.使用includes的处理方式
// 第一个参数 查找的值
// 第二个参数 从第几个索引开始
if (num.includes(2, 1)) {
  console.log("该数字存在~");
}
// 它比indexOf好的地方在于它可以判断NaN
console.log(num.includes(NaN));
```

