假如我们使用生成器的话

```javascript
function one(){
	setTimeout(()=>{
		console.log('1');
		Iterator.next();
	},1000)
}
function two(){
	setTimeout(()=>{
		console.log('2');
		Iterator.next();
	},2000)
}
function three(){
	setTimeout(()=>{
		console.log('3');
	},3000)
}
function * fn(){
	yield one();
	yield two();
	yield three();
}
let Iterator = fn();
Iterator.next();
```

假如我们改为订单数据的话，我们要获取里面的值的话，就可以使用 next 方式来传递值

```javascript
function one(){
	setTimeout(()=>{
		let name = '张三'
		Iterator.next(name);
	},1000)
}
function two(){
	setTimeout(()=>{
		let age = 18;
		Iterator.next(age);
	},2000)
}
function three(){
	setTimeout(()=>{
		let sex = '男'
		Iterator.next(sex);
	},3000)
}
function * fn(){
	let name = yield one();
    console.log(name);
	let age = yield two();
    console.log(age);
	let sex = yield three();
    console.log(sex);
}
let Iterator = fn();
Iterator.next();
```

## 99.5 Promise 实践

假如我们使用回调地狱来做的话就是下面这个样子

需求是将 3 个文件依次链接在一起

```javascript
fs.readFile('./1.txt',(err,data1)=>{
	fs.readFile('./1.txt',(err,data2)=>{
		fs.readFile('./1.txt',(err,data3)=>{
			let result = data1 + '\n' + data2 + '\n' + data3;
			console.log(result);
		});
	});
});
```

这个就可以避免回调地狱了，但是说句实话，理解了之后再看的话可能是挺方便的，但是观感确实没有回调地狱好看，可能是我水平不是很够吧

```javascript
const fs = require('fs');

//第一个Promise，读取1.txt
const p = new Promise((resolve, reject) => {
	fs.readFile('./1.txt', (err, data) => {
		resolve(data);	//将1.txt传达then()里面value
	});
});

p.then(value => {	//此时这里的value表示的是1.txt
	return new Promise((resolve, reject) => {
		fs.readFile('./2.txt', (err, data) => {
			resolve([value,data]);
	//这个时候就是一个数组,[1.txt,2.txt],我们将他传给then()
		});
	})
}).then(value => {	//采用链式调用，返回值给了他
	return new Promise((resolve, reject) => {
		fs.readFile('./3.txt', (err, data) => {
			value.push(data);	//将3.txt压进数组里面[1.txt,2.txt,3.txt]
			resolve(value);	//再将数组传出来
		});
	})
}).then(value => {	//数组传到了这个value的值里面
	console.log(value.join('\n'));	//我们将数组连接
});
```

