class ScopeSandbox {
  constructor() {
    this.proxy = new Proxy(Object.create(null), {
      has: () => true, // 欺骗 with 语句
      get: (target, key) => {
        if (key in this.apiWhitelist) {
          return this.apiWhitelist[key]
        }
        return undefined // 阻止访问原生全局对象
      },
      set: () => false // 禁止设置全局变量
    })
  }

  execute(code) {
    const wrapper = `
      (function(proxy) {
        with(proxy) {
          ${code}
        }
      })
    `
    return new Function('proxy', wrapper)(this.proxy)
  }
}
```

