要实现一个符合 **Promises/A+ 规范** 的 `Promise`，需要深入理解其核心机制。以下是分步骤的详细实现过程，包含关键代码和原理说明：

---

### **一、基础框架：状态管理与构造函数**
#### 1. 定义三种状态
```javascript
const PENDING = 'pending'
const FULFILLED = 'fulfilled'
const REJECTED = 'rejected'
```

#### 2. 构造函数
```javascript
class MyPromise {
  constructor(executor) {
    this.state = PENDING   // 初始状态
    this.value = undefined // 成功值
    this.reason = undefined // 失败原因
    this.onFulfilledCallbacks = [] // 成功回调队列
    this.onRejectedCallbacks = []  // 失败回调队列

    // 定义 resolve 和 reject 函数
    const resolve = (value) => {
      if (this.state === PENDING) {
        this.state = FULFILLED
        this.value = value
        this.onFulfilledCallbacks.forEach(fn => fn()) // 触发回调
      }
    }

    const reject = (reason) => {
      if (this.state === PENDING) {
        this.state = REJECTED
        this.reason = reason
        this.onRejectedCallbacks.forEach(fn => fn()) // 触发回调
      }
    }

    // 执行 executor
    try {
      executor(resolve, reject) // 同步执行
    } catch (err) {
      reject(err) // 捕获同步错误
    }
  }
}
```

---

### **二、实现 `then` 方法（核心）**
#### 1. 方法签名
```javascript
then(onFulfilled, onRejected) {
  // 实现值穿透（符合 Promises/A+ 规范）
  onFulfilled = typeof onFulfilled === 'function' ? onFulfilled : value => value
  onRejected = typeof onRejected === 'function' ? onRejected : reason => { throw reason }

  // 返回新 Promise 以实现链式调用
  const promise2 = new MyPromise((resolve, reject) => {
    // 统一处理回调
    const handleCallback = (callback, value) => {
      setTimeout(() => { // 确保异步执行（规范要求）
        try {
          const x = callback(value)
          resolvePromise(promise2, x, resolve, reject)
        } catch (err) {
          reject(err)
        }
      }, 0)
    }

    if (this.state === FULFILLED) {
      handleCallback(onFulfilled, this.value)
    } else if (this.state === REJECTED) {
      handleCallback(onRejected, this.reason)
    } else { // PENDING 状态时暂存回调
      this.onFulfilledCallbacks.push(() => {
        handleCallback(onFulfilled, this.value)
      })
      this.onRejectedCallbacks.push(() => {
        handleCallback(onRejected, this.reason)
      })
    }
  })

  return promise2
}
```

#### 2. 解析回调返回值（关键）
```javascript
function resolvePromise(promise2, x, resolve, reject) {
  if (promise2 === x) { // 禁止循环引用
    return reject(new TypeError('Chaining cycle detected'))
  }

  // 处理 thenable 对象或 Promise
  if ((typeof x === 'object' && x !== null) || typeof x === 'function') {
    let then
    try {
      then = x.then // 可能抛出错误（如属性访问器）
    } catch (err) {
      return reject(err)
    }

    if (typeof then === 'function') {
      let called = false // 防止多次调用
      try {
        then.call(
          x,
          y => {
            if (called) return
            called = true
            resolvePromise(promise2, y, resolve, reject) // 递归解析
          },
          r => {
            if (called) return
            called = true
            reject(r)
          }
        )
      } catch (err) {
        if (!called) reject(err)
      }
    } else {
      resolve(x) // 普通对象
    }
  } else {
    resolve(x) // 基础类型值
  }
}
```

