```javascript
class ResourceMonitor {
  constructor() {
    this.usage = {
      memory: 0,
      network: 0,
      storage: 0
    };
  }

  createProxy(api) {
    return new Proxy(api, {
      get: (target, prop) => {
        if (prop === 'fetch') {
          return (...args) => {
            this.usage.network++;
            return target[prop](...args);
          };
        }
        return target[prop];
      }
    });
  }
}
